import * as T from './vendor/three.module.js';
function glowTexture(){const c=document.createElement('canvas');c.width=c.height=64;const ctx=c.getContext('2d'),g=ctx.createRadialGradient(32,32,0,32,32,32);g.addColorStop(0,'#fff');g.addColorStop(.2,'#ffffffdd');g.addColorStop(1,'#ffffff00');ctx.fillStyle=g;ctx.fillRect(0,0,64,64);return new T.CanvasTexture(c);}
export function createEffects(scene,dark=false){const count=90,positions=new Float32Array(count*3),colors=new Float32Array(count*3);for(let i=0;i<count;i++){positions.set([(i*3.17%25)-12,(i*1.37%5)+.5,(i*2.91%12)-6],i*3);colors.set(dark?[1,.7,.3]:[1,.9,.63],i*3);}const geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.BufferAttribute(positions,3));geometry.setAttribute('color',new T.BufferAttribute(colors,3));const dots=new T.Points(geometry,new T.PointsMaterial({size:dark?.06:.045,map:glowTexture(),transparent:true,vertexColors:true,depthWrite:false,blending:T.AdditiveBlending,opacity:.55}));scene.add(dots);const size=64,burstGeometry=new T.BufferGeometry(),burstPositions=new Float32Array(size*3);burstGeometry.setAttribute('position',new T.BufferAttribute(burstPositions,3));const burst=new T.Points(burstGeometry,new T.PointsMaterial({color:0xffd273,size:.13,map:glowTexture(),transparent:true,depthWrite:false,blending:T.AdditiveBlending}));scene.add(burst);burst.visible=false;const dustPositions=new Float32Array(36*3),dustGeo=new T.BufferGeometry();dustGeo.setAttribute('position',new T.BufferAttribute(dustPositions,3));const dust=new T.Points(dustGeo,new T.PointsMaterial({color:0xc7af83,size:.55,map:glowTexture(),transparent:true,depthWrite:false,opacity:.25}));scene.add(dust);return{dust,dustPositions,dots,positions,burst,burstPositions,origin:new T.Vector3(),born:-10,dustOrigin:new T.Vector3(),dark};}
export function emit(fx,time,origin){fx.origin.copy(origin);fx.born=time;fx.burst.visible=true;}
export function animateEffects(fx,time,moving=0){fx.dust.visible=moving>0&&!fx.dark;fx.dust.material.opacity=moving*.28;for(let i=0;i<36;i++){const a=(time*1.4+i*.19)%1;fx.dustPositions[i*3]=-5.5-a*2.1;fx.dustPositions[i*3+1]=.35+a*.85;fx.dustPositions[i*3+2]=(i%2?1:-1)*(1.3+Math.sin(i)*a*.3);}fx.dust.geometry.attributes.position.needsUpdate=true;const p=fx.positions;for(let i=0;i<p.length/3;i++){p[i*3+1]=.5+((time*.055+i*1.37)%5);p[i*3+2]=((i*2.91)%12)-6+Math.sin(time*.35+i)*.15;}fx.dots.geometry.attributes.position.needsUpdate=true;const life=time-fx.born;if(life>=0&&life<1.6){for(let i=0;i<64;i++){const a=i*2.399,r=.2+life*(.9+(i%5)*.15);fx.burstPositions[i*3]=fx.origin.x+Math.cos(a)*r;fx.burstPositions[i*3+1]=fx.origin.y+life*2.3-life*life*1.2+(i%4)*.07;fx.burstPositions[i*3+2]=fx.origin.z+Math.sin(a)*r;}fx.burst.material.opacity=1-life/1.6;fx.burst.geometry.attributes.position.needsUpdate=true;}else fx.burst.visible=false;}
export function studioLighting(renderer,scene){const envScene=new T.Scene();envScene.background=new T.Color(0x788e91);const panels=[{color:0xfff4d8,pos:[0,8,0],size:[18,1,18]},{color:0xe2eeff,pos:[-9,3,0],size:[1,12,18]},{color:0xd1e2b9,pos:[9,2,0],size:[1,9,18]}];for(const p of panels){const m=new T.Mesh(new T.BoxGeometry(...p.size),new T.MeshBasicMaterial({color:p.color}));m.position.set(...p.pos);envScene.add(m);}const pmrem=new T.PMREMGenerator(renderer);const target=pmrem.fromScene(envScene,.08);scene.environment=target.texture;scene.environmentIntensity=.23;pmrem.dispose();envScene.traverse(o=>{o.geometry?.dispose();o.material?.dispose();});return target;}
